/// One registered artifact: its identity (digest), its labels, what it is, and where it came
/// from.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Artifact {
    pub digest: ArtifactDigest,
    pub name: String,
    pub version: String,
    pub kind: ArtifactKind,
    pub size: u64,
    /// Where its bytes were read from when registered (`file:/absolute/path`).
    pub source: String,
    pub by: PrincipalId,
    pub at: Timestamp,
}

impl Artifact {
    /// `NAME@VERSION`.
    pub fn label(&self) -> String {
        format!("{}@{}", self.name, self.version)
    }

    /// The local path its bytes were registered from, when its source is a file.
    pub fn source_path(&self) -> Option<&Path> {
        self.source.strip_prefix("file:").map(Path::new)
    }

/// Every registered artifact, by digest and by label.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct ArtifactBook {
    by_digest: BTreeMap<ArtifactDigest, Artifact>,
    by_label: BTreeMap<(String, String), ArtifactDigest>,
}

/// The artifact `reference` names: `sha256:<hex>`, or `NAME@VERSION`.
pub fn resolve(&self, reference: &str) -> Result<Artifact, ArtifactError> {
    let digest = if reference.starts_with(PREFIX) {
        ArtifactDigest::parse(reference)?
    } else {
        let (name, version) = reference.split_once('@').ok_or_else(|| {
            ArtifactError::Malformed(format!("{reference}: NAME@VERSION or sha256:<hex>"))
        })?;
        *self
            .by_label
            .get(&(name.to_owned(), version.to_owned()))
            .ok_or_else(|| ArtifactError::Unknown(reference.to_owned()))?
    };
    let mut artifact = self
        .by_digest
        .get(&digest)
        .cloned()
        .ok_or_else(|| ArtifactError::Unknown(reference.to_owned()))?;
    if let Some((name, version)) = reference.split_once('@') {
        artifact.name = name.to_owned();
        artifact.version = version.to_owned();
    }
    Ok(artifact)
}

/// Every label and the digest it names, in label order.
pub fn labels(&self) -> impl Iterator<Item = (String, ArtifactDigest)> + '_ {
    self.by_label
        .iter()
        .map(|((n, v), d)| (format!("{n}@{v}"), *d))
}

pub struct NativeArtifactStore {
    store: FactStore<ArtifactBook, ArtifactFact>,
}

impl NativeArtifactStore {
    pub fn open(path: impl AsRef<Path>) -> Result<Self, FactStoreError> {
        Ok(Self {
            store: FactStore::open(path)?,
        })
    }

    /// Records `fact` if it changes the book (`Ok(true)`); a retry or a refusal writes nothing.
    pub fn record(&mut self, fact: ArtifactFact) -> Result<bool, ArtifactStoreError> {
        if !self
            .store
            .resolver()
            .admits(&fact)
            .map_err(ArtifactStoreError::Refused)?
        {
            return Ok(false);
        }
        self.store.record(fact).map_err(ArtifactStoreError::Log)?;
        Ok(true)
    }

    pub fn book(&self) -> &ArtifactBook {
        self.store.resolver()
    }
}

//! Artifacts through the governed spine (`world::artifact`). The book is canonical history
//! (`artifacts.log`, replicated like every log); registering reads the bytes, so the digest is
//! what the file holds, never what a caller claims, and needs `artifact.register` on the
//! authority resource. A provider may name an artifact -- `artifact:NAME@VERSION` or
//! `artifact:sha256:<hex>` -- anywhere a provider is named (binding a program to a resource,
//! submitting a job, declaring or deploying a service): it is resolved here, once, into the
//! runtime's provider, which pins the content (`process:PATH@sha256:<hex>`), so a revision of a
//! service is its artifact's digest and the executor runs exactly those bytes
//! (`process_executor`).

/// Registers the file at `path` (absolute) as artifact `name`@`version` of `kind`, by `who`,
/// who must hold `artifact.register` on the authority resource. Its digest and size are read
/// from the file. `Ok(false)`: the same bytes were already that version.
pub fn register_artifact(
    &mut self,
    who: &PrincipalId,
    name: &str,
    version: &str,
    kind: ArtifactKind,
    path: &Path,
    at: Timestamp,
) -> Result<bool, HostError> {
    self.writable()?;
    self.require(who, ARTIFACT_REGISTER, &resource(AUTHORITY_RESOURCE)?, at)?;
    if !path.is_absolute() {
        return Err(HostError::Invalid(format!(
            "{}: an artifact is registered from an absolute path",
            path.display()
        )));
    }
    let (digest, size) = ArtifactDigest::of_file(path)
        .map_err(|e| HostError::Rejected(format!("{}: {e}", path.display())))?;
    self.artifacts
        .record(ArtifactFact::Registered(Artifact {
            digest,
            name: name.to_owned(),
            version: version.to_owned(),
            kind,
            size,
            source: format!("file:{}", path.display()),
            by: who.clone(),
            at,
        }))
        .map_err(|e| match e {
            ArtifactStoreError::Refused(e) => HostError::Rejected(e.to_string()),
            ArtifactStoreError::Log(e) => storage(format!("{e:?}")),
        })
}

/// The artifact `reference` names (`NAME@VERSION` or `sha256:<hex>`).
pub fn artifact(&self, reference: &str) -> Result<Artifact, HostError> {
    self.artifacts
        .book()
        .resolve(reference)
        .map_err(|e| HostError::Rejected(e.to_string()))
}

/// Every artifact label and the digest it names.
pub fn artifacts(&self) -> Vec<(String, ArtifactDigest)> {
    self.artifacts.book().labels().collect()

