/// Reads an observed work outcome only after it is canonical on `on`. Current observation
/// rights are required, including for historical work; a request key alone reveals nothing.
/// Pending, unobserved or partly unknown outcomes return None and never authorize execution.
pub fn work_evidence(
    &self,
    who: &PrincipalId,
    on: &ResourceId,
    key: &str,
    at: Timestamp,
) -> Result<Option<Evidence>, HostError> {
    self.require(who, "resource.observe", on, at)?;
    let effect = Self::evidence_of(key)?;
    let canonical_key = lineara::canonicalization::idempotency_key(&effect.work_run, EFFECT);
    let Some(revision) = self
        .world
        .applied(on.as_str(), &canonical_key)
        .map_err(storage)?
    else {
        return Ok(None);
    };
    let Some(evidence) = EvidenceStore::get(&self.evidence, &effect).map_err(storage)? else {
        return Ok(None);
    };
    let EvidenceProof::ProviderAck(receipt) = &evidence.proof else {
        return Ok(None);
    };
    let Some(report) = reported(receipt).filter(WorkReport::is_known) else {
        return Ok(None);
    };
    let event = self
        .world
        .replay(on.as_str())
        .map_err(storage)?
        .into_iter()
        .find(|(r, _)| *r == revision)
        .map(|(_, event)| event);
    let Some(ResourceEvent {
        change:
            ResourceChange::LeaseSettled {
                lease,
                consumed,
                completed,
                ..
            },
        ..
    }) = event
    else {
        return Ok(None);
    };
    if consumed != report.consumed
        || completed != report.completed
        || !receipt.contains(&format!(" ran effect {effect} under lease {lease} · work "))
    {
        return Err(HostError::Rejected(format!(
            "{key}: work evidence disagrees with its canonical settlement"
        )));
    }
    Ok(Some(evidence))

