pub struct EffectId(pub u64);

/// The globally unique identity of one effect: the WorkRun it belongs to and its number within
/// that run. Effect ids alone repeat across runs; anything that outlives a run's memory --
/// evidence, retention, legal hold, canonicalization -- is keyed by this, never by
/// [`EffectId`] alone.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct EffectRef {
    pub work_run: WorkRunId,
    pub effect: EffectId,
}

impl std::fmt::Display for EffectRef {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}#{}", self.work_run, self.effect.0)
    }
}

/// Why a retry attempt could not start.
/// What a WorkRun was started for: a SHA-256 over the request's identifying parts (its family,
/// who asks, which entities, which change -- whatever the caller says makes two requests the
/// same request). A run id is the caller's idempotency key; binding the run to its request
/// makes a key reused for a different request refused instead of resumed (the check Stripe
/// and AWS make when an idempotency key comes back with other parameters), so completed or
/// evidenced work can never be attributed to another request.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct RequestDigest(pub [u8; 32]);

impl RequestDigest {
    /// The digest of `parts`, each length-prefixed so that no two part lists share one.
    pub fn of(parts: &[&[u8]]) -> Self {
        use genora_primitives::digest::Sha256;
        let mut hash = Sha256::new();
        hash.update(b"chronica.request.v1\0");
        for part in parts {
            hash.update((part.len() as u64).to_le_bytes());
            hash.update(part);
        }
        Self(hash.finalize())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum WorkRunError {
    /// One or more effects from the current attempt have not yet been durably acknowledged.
    /// Starting a new attempt now could run concurrently with the still-unacknowledged one and
    /// duplicate a side effect -- the caller must wait for these to drain, never override it.
    EffectsStillPending { pending: usize },
}

/// Starts the next retry attempt, advancing the fencing token -- only once every effect from
/// the current attempt has drained. Returns the new generation on success.
pub fn begin_retry(&mut self) -> Result<Generation, WorkRunError> {
    if !self.pending_effects.is_empty() {
        return Err(WorkRunError::EffectsStillPending {
            pending: self.pending_effects.len(),
        });
    }
    self.generation = self.generation.next();
    Ok(self.generation)
}

pub fn check_request(stored: &WorkRun, new: &WorkRun) -> Result<(), WorkRunStoreError> {
    match (stored.request(), new.request()) {
        (Some(a), Some(b)) if a == b => Ok(()),
        (None, _) => Ok(()),
        _ => Err(WorkRunStoreError::RequestMismatch(format!(
            "{} is bound to another request",
            stored.id()
        ))),
    }
}

