/// What a work run under a lease reports when it ends: what it consumed of the lease's
/// quantity, and whether it completed -- each `None` when it is not known. Unknown is not a
/// fact: a run whose outcome nobody observed reports neither, and nothing is ever filled in for
/// it (no invented failure, no invented consumption).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WorkReport {
    pub consumed: Option<i64>,
    pub completed: Option<bool>,
}

impl WorkReport {
    /// Nothing is known of the run: whether it ran, what it consumed, how it ended.
    pub const UNKNOWN: Self = Self {
        consumed: None,
        completed: None,
    };

    /// A run whose provider reported both.
    pub fn known(consumed: i64, completed: bool) -> Self {
        Self {
            consumed: Some(consumed),
            completed: Some(completed),
        }
    }

    /// Whether both are known.
    pub fn is_known(&self) -> bool {
        self.consumed.is_some() && self.completed.is_some()
    }
}

