//! Strict, record-aware decoding over the existing canonical log envelope.
//!
//! A source job snapshot is recorded input, never a native job claim or authority.
//! This module owns no log, writer, World, claim token or automatic dispatch.

use crate::resource_event::{ResourceEvent, RESOURCE_EVENT_SCHEMA};
use crate::resource_reducer::ResourceStateReducer;
