/// Local payload schema, not an Esellios wire or executable job lifecycle.
pub const SOURCE_JOB_SNAPSHOT_SCHEMA: &str = "chronica.source-job.snapshot";

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum NativeEvent {
    Resource(ResourceEvent),
    SourceJobSnapshot(Box<SourceJobSnapshot>),
}

/// Retains every original identity, position, schema, evidence link and raw payload.
/// The native log owns frame/checksum validation; this decoder claims no integrity or
/// authority attestation and must receive records from the owning validated log.
#[derive(Debug)]
pub struct DecodedRecord<'a> {
    pub original: &'a CanonicalLogRecord,
    pub event: NativeEvent,
}

/// Dispatches by explicit schema only. It never guesses from payload bytes, treats an
/// unknown schema as a resource, or silently skips a record in a mixed history.
pub fn decode_record(record: &CanonicalLogRecord) -> Result<DecodedRecord<'_>, DecodeError> {
    if record.kind != CanonicalLogRecordKind::CanonicalEvent {
        return Err(DecodeError::Invalid {
            field: "world record kind",
            reason: "expected canonical event".into(),
        });
    }
    let event = match record.event_reference.as_str() {
        RESOURCE_EVENT_SCHEMA => NativeEvent::Resource(ResourceEvent::decode(&record.payload)?),
        SOURCE_JOB_SNAPSHOT_SCHEMA => {
            NativeEvent::SourceJobSnapshot(Box::new(SourceJobSnapshot::decode(&record.payload)?))
        }
        _ => {
            return Err(DecodeError::Invalid {
                field: "world event schema",
                reason: format!("unsupported schema {:?}", record.event_reference),
            })
        }
    };
    Ok(DecodedRecord {
        original: record,
        event,
    })
}

