    decode(receipt).ok().map(|_| WorkReport::known(1, true))

//! Governed local validation and immutable capture of source assertions.
//!
//! This bounded provider imports bytes; it neither actuates a pump nor authenticates source
//! rights, clocks or outcomes. `Unknown` remains source data. The known local report accounts
//! for one CPU unit of validation, using an existing lease through the normal execution spine.

use crate::{allocation::WorkDone, storage, Checks, Host, HostError, EFFECT};
use genora_primitives::{Generation, Timestamp};
