pub const PROVIDER: &str = "chronica.pump-source-import";
pub const PROVIDER_VERSION: &str = "1";
pub const PARAMETER: &str = "cpu_units";
pub const UNIT: &str = "unit";

/// One native import fence for this canonical resource/lease pair. Source inputs deliberately
/// do not affect this key: changed inputs must not escape a prior unknown local execution.
pub fn source_import_key(resource: &ResourceId, lease: &str) -> String {
    let digest = RequestDigest::of(&[
        b"chronica.source-import.lease-fence.v1",
        resource.as_str().as_bytes(),
        lease.as_bytes(),
    ]);
    genora_primitives::digest::hex(&digest.0)
}

/// The provider retains the result of its actual `perform`, then supplies original assertions
/// with the Host's complete target binding. It must not fabricate a result before execution.
pub trait SourceObservationWork: LeaseWork {
    fn source_observation(&self, target: TargetBinding) -> Result<SourceObservation, String>;
}

/// Original target context, independent of the source's raw clock and authority assertions.
/// `amount` is the existing lease's amount; this local operation consumes exactly one unit.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SourceImportContext {
    pub requester: PrincipalId,
    pub resource: ResourceId,
    pub holding: HoldingId,
    pub purpose: String,
    pub lease: String,
    pub provider: String,
    pub provider_version: String,
    pub clock: String,
    pub requested_at: Timestamp,
    pub expires_at: Timestamp,
    pub generation: Generation,
    pub parameter: Parameter,
    pub unit: Unit,
    pub amount: i64,
}

fn refused(reason: impl std::fmt::Display) -> HostError {
    HostError::Rejected(format!("source observation: {reason}"))
}

impl SourceImportContext {
    pub fn work_key(&self) -> String {
        source_import_key(&self.resource, &self.lease)
    }

    /// Commits target context and provider's original byte identity. No source identity is
    /// converted to a target principal, Holding, generation or authority witness.
    pub fn request_binding(&self, source: &RequestDigest) -> Result<RequestDigest, HostError> {
        for (name, value) in [
            ("purpose", self.purpose.as_str()),
            ("lease", self.lease.as_str()),
            ("clock", self.clock.as_str()),
        ] {
            if value.is_empty() || value.len() > 1024 || value.chars().any(char::is_control) {
                return Err(refused(format!("invalid {name}")));
            }
        }
        crate::purpose_of(&self.purpose)?;
        if self.provider != PROVIDER
            || self.provider_version != PROVIDER_VERSION
            || self.parameter.as_str() != PARAMETER
            || self.unit.as_str() != UNIT
            || self.amount < 1
            || self.generation != Generation::INITIAL
        {
            return Err(refused(
                "unsupported provider, version, CPU quantity/unit, amount or generation",
            ));
        }
        Ok(RequestDigest::of(&[
            b"chronica.source-import.context.v1",
            self.requester.as_str().as_bytes(),
            self.resource.as_str().as_bytes(),
            self.holding.as_str().as_bytes(),
            self.purpose.as_bytes(),
            self.lease.as_bytes(),
            self.provider.as_bytes(),
            self.provider_version.as_bytes(),
            self.clock.as_bytes(),
            &self.requested_at.0.to_le_bytes(),
            &self.expires_at.0.to_le_bytes(),
            &self.generation.0.to_le_bytes(),
            self.parameter.as_str().as_bytes(),
            self.unit.as_str().as_bytes(),
            &self.amount.to_le_bytes(),
            &source.0,
        ]))

impl Host {
    /// Validates locally only after current purpose/quantity-aware admission. The existing
    /// lease is not allocated again. A durable pending fence precedes the verifier. Any prior
    /// request without a valid receipt remains held; this API never reexecutes it.
    pub fn import_source_observation(
        &mut self,
        context: &SourceImportContext,
        work: &mut impl SourceObservationWork,
        key: &str,
        at: Timestamp,
    ) -> Result<WorkDone, HostError> {
        self.writable()?;
        if key != context.work_key() {
            return Err(refused(
                "request key must be the deterministic resource/lease import fence",
            ));
        }
        let source = work
            .request_binding()
            .ok_or_else(|| refused("provider lacks original input binding"))?;
        let binding = context.request_binding(&source)?;
        let id = WorkRunId::try_from(key).map_err(|e| crate::invalid("request key", e))?;
        self.owns(&context.resource, at)?;
        if self.holding_at(&context.resource, at)? != Some(context.holding.clone()) {
            return Err(refused("canonical Holding differs"));
        }
        let previous = self.runs.restore(&id).map_err(storage)?;
        let allocation = if let Some(run) = previous {
            // Retrying is observation/reconciliation, not renewed execution admission.
            self.observe_for(
                &context.requester,
                &context.resource,
                &context.holding,
                Some(&context.purpose),
                None,
                at,
            )?;
            if run.current_generation() != context.generation
                || run.pending_effect_ids().iter().any(|e| *e != EFFECT)
            {
                return Err(refused(
                    "unsupported stored generation or pending effects remain held",
                ));
            }
            None
        } else {
            // Canonical consumption cannot account for an unobserved local import. Until a
            // complete receipt is reconciled, admit no additional work in this bounded lane,
            // even under another lease/Holding. Expiry alone is not evidence of zero cost.
            if self.has_unresolved_source_import()? {
                return Err(refused("another local source import remains unresolved"));
            }
            if context.requested_at > at || at >= context.expires_at {
                return Err(refused("request is future-issued or expired"));
            }
            let state = self
                .world
                .current(&context.resource)
                .map_err(storage)?
                .0
                .ok_or_else(|| refused("budget resource does not exist"))?;
            if state.lifecycle() != ResourceLifecycleState::Active {
                return Err(refused("budget resource is not Active"));
            }

self.work_under_lease_with_codec(
    &context.requester,
    &context.resource,
    &context.lease,
    &context.provider,
    work,
    key,
    at,
    Some(binding),
    Checks {
        via: Some(&context.provider),
        purpose: Some(&context.purpose),
        quantity: Some(context.parameter.as_str()),
        authority_value: Some(1),
        allocation,
        ..Checks::default()
    },
    Some(&context.provider_version),
    |work, target, report| {
        if *report != WorkReport::known(1, true) {
            return Err(refused(
                "local verifier did not report known one-unit completion",
            ));
        }
        let observation = work.source_observation(target.clone()).map_err(refused)?;
        let receipt = codec::encode(&observation).map_err(refused)?;
        codec::decode_for(&receipt, target).map_err(refused)?;
        Ok(receipt)
    },
    |receipt, target| {
        codec::decode_for(receipt, target).map_err(refused)?;
        Ok(Some(WorkReport::known(1, true)))
    },
)

/// Current Holding and purpose-aware read rights precede all historical evidence reads.
/// A key alone discloses nothing. No original source file, import right, retry or pump
/// state transition is needed or produced by observing the committed assertion bytes.
#[allow(clippy::too_many_arguments)]
pub fn observe_source_observation(
    &self,
    observer: &PrincipalId,
    on: &ResourceId,
    holding: &HoldingId,
    purpose: Option<&str>,
    key: &str,
    at: Timestamp,
) -> Result<Option<SourceObservation>, HostError> {
    self.observe_for(observer, on, holding, purpose, None, at)?;
    self.source_observation_receipt(on, key)
}

fn source_observation_receipt(
    &self,
    on: &ResourceId,
    key: &str,
) -> Result<Option<SourceObservation>, HostError> {
    let effect = Self::evidence_of(key)?;
    let Some(run) = self.runs.restore(&effect.work_run).map_err(storage)? else {
        return Ok(None);
    };
    let Some(request) = run.request().copied() else {
        return Err(refused("unbound historical run"));
    };
    if run.current_generation() != Generation::INITIAL
        || run.pending_effect_ids().iter().any(|e| *e != EFFECT)
    {
        return Err(refused("unsupported stored generation or pending effects"));
    }
    let canonical = lineara::canonicalization::idempotency_key(&effect.work_run, EFFECT);
    let Some(revision) = self
        .world
        .applied(on.as_str(), &canonical)
        .map_err(storage)?
    else {
        return Ok(None);
    };
    let event = self
        .world
        .replay(on.as_str())
        .map_err(storage)?
        .into_iter()
        .find(|(r, _)| *r == revision)
        .map(|(_, event)| event);
    let Some(ResourceEvent {
        change:
            ResourceChange::LeaseSettled {
                lease,
                parameter,
                consumed: Some(1),
                completed: Some(true),
            },
        ..
    }) = event
    else {
        return Err(refused(
            "canonical event is not a one-unit completed settlement",
        ));
    };
    if parameter.as_str() != PARAMETER {
        return Err(refused("canonical settlement has another quantity"));
    }
    let Some(evidence) = EvidenceStore::get(&self.evidence, &effect).map_err(storage)? else {
        return Ok(None);
    };
    if evidence.effect != effect {
        return Err(refused("evidence effect differs"));
    }
    let EvidenceProof::ProviderAck(receipt) = evidence.proof else {
        return Ok(None);
    };
    let expected = TargetBinding {
        effect,
        generation: run.current_generation(),
        lease,
        provider: PROVIDER.into(),
        request,
    };
    codec::decode_for(&receipt, &expected)
        .map(Some)
        .map_err(refused)

pub fn work_under_lease(
    &mut self,
    who: &PrincipalId,
    on: &ResourceId,
    lease: &str,
    provider: &str,
    work: &mut impl LeaseWork,
    key: &str,
    at: Timestamp,
) -> Result<WorkDone, HostError> {
    // This newly introduced local provider has a dedicated complete receipt codec and
    // deterministic lease fence. Generic work cannot bypass either door or reuse a lease
    // whose import may have consumed an unobserved unit. Other historical providers keep
    // their existing request/receipt grammar. This fences only this Host's writer custody.
    let source_key = crate::source_observation::source_import_key(on, lease);
    if provider == crate::source_observation::PROVIDER
        || self
            .runs
            .restore(
                &WorkRunId::try_from(source_key.as_str())
                    .map_err(|e| invalid("source import fence", e))?,
            )
            .map_err(storage)?
            .is_some()
    {
        return Err(HostError::Rejected(
            "source import lease requires its dedicated fenced pathway".into(),
        ));
    }
    let binding = work.request_binding();
    self.work_under_lease_with_codec(
        who,
        on,
        lease,
        provider,
        work,
        key,
        at,
        binding,
        Checks {
            via: Some(provider),
            ..Checks::default()
        },
        None,
        |work, target, report| {
            let result = work.outcome_evidence();
            if result.is_some() && !report.is_known() {
                return Err(HostError::Rejected(
                    "native result evidence cannot turn an unknown work outcome into a fact"
                        .into(),
                ));
            }
            match result.as_deref() {
                Some(result) => lineara::work_receipt::encode(
                    &target.provider,
                    &target.effect,
                    &target.lease,
                    report,
                    Some(result),
                )
                .map_err(|e| HostError::Rejected(format!("native result evidence: {e:?}"))),
                None => Ok(work_receipt(
                    &target.provider,
                    &target.effect,
                    &target.lease,
                    report,
                )),
            }
        },
        |receipt, _| Ok(reported(receipt)),
    )
}

/// Same execution spine, with a private receipt codec. New callers must bind their complete
/// inputs and validate the full persisted target before a receipt can settle any lease.
#[allow(clippy::too_many_arguments)]
pub(super) fn work_under_lease_with_codec<W: LeaseWork>(
    &mut self,
    who: &PrincipalId,
    on: &ResourceId,
    lease: &str,
    provider: &str,
    work: &mut W,
    key: &str,
    at: Timestamp,
    binding: Option<RequestDigest>,
    checks: Checks<'_>,
    expected_version: Option<&str>,
    encode: impl FnOnce(
        &W,
        &lineara::source_observation::TargetBinding,
        &WorkReport,
    ) -> Result<String, HostError>,
    decode: impl Fn(
        &str,
        &lineara::source_observation::TargetBinding,
    ) -> Result<Option<WorkReport>, HostError>,
) -> Result<WorkDone, HostError> {

// Optional native input binding extends only that provider's new requests. The default
// retains every historical request digest and receipt byte-for-byte.
let request = lease_work_request(who, on, lease, provider, binding.as_ref());
let previous = self.runs.restore(&run_id).map_err(storage)?;
if let Some(held_run) = &previous {
    if held_run.request().is_some_and(|held| held != &request)
        || (binding.is_some() && held_run.request().is_none())
    {
        return Err(HostError::RequestKeyReused(format!(
            "{key} is bound to another work input"
        )));
    }
}
let effect = EffectRef {
    work_run: run_id.clone(),
    effect: EFFECT,
};
let receipt_target = lineara::source_observation::TargetBinding {
    effect: effect.clone(),
    generation: previous
        .as_ref()
        .map(|r| r.current_generation())
        .unwrap_or(genora_primitives::Generation::INITIAL),
    lease: lease.to_owned(),
    provider: provider.to_owned(),
    request,
};

let settle = |report: &WorkReport| ResourceEvent {
    occurred_at: at,
    change: ResourceChange::LeaseSettled {
        lease: lease.to_owned(),
        parameter: held.parameter.clone(),
        consumed: report.consumed,
        completed: report.completed,
    },
};
// A run evidenced before a crash is settled with what it reported.
let evidenced = match EvidenceStore::get(&self.evidence, &Self::evidence_of(key)?)
    .map_err(storage)?
    .map(|e| e.proof)
{
    Some(EvidenceProof::ProviderAck(receipt)) => decode(&receipt, &receipt_target)?,
    _ => None,
};
if let Some(report) = evidenced {
    if let Some(outcome) = resume_request(
        &mut self.runs,
        &mut self.evidence,
        &run_id,
        &request,
        settle(&report),
        Target {
            world: &mut self.world,
            entity: on.as_str(),
            expected: head,
            to_event: |e| e,
        },
    )? {
        return Ok(WorkDone {
            outcome: outcome.into(),
            report,
        });
    }
}
// Native work with no durable observed outcome cannot authorize its own retry. Keep
// pending work unknown, even though this particular kernel is pure and deterministic.
if binding.is_some() && previous.is_some() {
    return Err(HostError::Rejected(format!(
        "{key}: work outcome remains unknown; native work was not re-executed"
    )));
}
let selected = self.admit(who, &action("resource.work")?, on, key, at, checks)?;
if expected_version.is_some_and(|version| selected.binding().version != version) {
    return Err(HostError::Rejected(
        "source import provider version differs from the request".into(),
    ));
}
if binding.is_some() {
    let mut begun = GovernedWorkRun::begin_for(run_id.clone(), selected.clone(), request);
    begun.run_mut().record_effect_emitted(EFFECT);
    self.runs.snapshot(begun.run()).map_err(storage)?;
}
let report = work
    .perform(&effect, lease, &held)
    .map_err(|e| HostError::Rejected(format!("{provider}: {e}")))?;
let receipt = encode(work, &receipt_target, &report)?;

/// Reads an observed work outcome only after it is canonical on `on`. Current observation
/// rights are required, including for historical work; a request key alone reveals nothing.
/// Pending, unobserved or partly unknown outcomes return None and never authorize execution.
pub fn work_evidence(
    &self,
    who: &PrincipalId,
    on: &ResourceId,
    key: &str,
    at: Timestamp,
) -> Result<Option<Evidence>, HostError> {
    self.require(who, "resource.observe", on, at)?;
    let effect = Self::evidence_of(key)?;
    let canonical_key = lineara::canonicalization::idempotency_key(&effect.work_run, EFFECT);
    let Some(revision) = self
        .world
        .applied(on.as_str(), &canonical_key)
        .map_err(storage)?
    else {
        return Ok(None);
    };
    let Some(evidence) = EvidenceStore::get(&self.evidence, &effect).map_err(storage)? else {
        return Ok(None);
    };
    let EvidenceProof::ProviderAck(receipt) = &evidence.proof else {
        return Ok(None);
    };
    let Some(report) = reported(receipt).filter(WorkReport::is_known) else {
        return Ok(None);
    };
    let event = self
        .world
        .replay(on.as_str())
        .map_err(storage)?
        .into_iter()
        .find(|(r, _)| *r == revision)
        .map(|(_, event)| event);
    let Some(ResourceEvent {
        change:
            ResourceChange::LeaseSettled {
                lease,
                consumed,
                completed,
                ..
            },
        ..
    }) = event
    else {
        return Ok(None);
    };
    if consumed != report.consumed
        || completed != report.completed
        || !receipt.contains(&format!(" ran effect {effect} under lease {lease} · work "))
    {
        return Err(HostError::Rejected(format!(
            "{key}: work evidence disagrees with its canonical settlement"
        )));
    }
    Ok(Some(evidence))

