pub const PROVIDER: &str = "chronica.pump-source-import";
pub const VERSION: &str = "1";
pub const SOURCE_COMMIT: &str = "c43b8de6997d3f9857371aa8bdac4d18e0a72b79";
pub const CORPUS_REVISION: &str = "0844ffa170f8990238ef27d563c261a9451ce9e6";

pub struct PumpObservationWork {
    corpus: Vec<u8>,
    case_id: String,
    phase: String,
    performed: Option<(EffectRef, String, VerifiedPumpObservation)>,
}
impl PumpObservationWork {
    pub fn new(corpus: Vec<u8>, case_id: impl Into<String>, phase: impl Into<String>) -> Self {
        Self {
            corpus,
            case_id: case_id.into(),
            phase: phase.into(),
            performed: None,
        }
    }
    pub fn verified(&self) -> Option<&VerifiedPumpObservation> {
        self.performed.as_ref().map(|(_, _, v)| v)
    }
}
impl LeaseWork for PumpObservationWork {
    fn request_binding(&self) -> Option<RequestDigest> {
        if self.corpus.len() > lineara::source_observation::MAX_CORPUS_BYTES
            || self.case_id.len() > lineara::source_observation::MAX_CASE_BYTES
            || self.phase.len() > lineara::source_observation::MAX_PHASE_BYTES
        {
            return None;
        }
        let mut selectors = Writer::new();
        selectors
            .u16(1)
            .str(SOURCE_COMMIT)
            .str(&self.case_id)
            .str(&self.phase);
        Some(RequestDigest::of(&[
            b"chronica.pump-source.local-import.v1",
            &selectors.finish(),
            &self.corpus,
        ]))
    }
    fn perform(
        &mut self,
        effect: &EffectRef,
        lease: &str,
        _: &world::lease::Lease,
    ) -> Check<WorkReport> {
        if let Some((known, known_lease, _)) = &self.performed {
            if known != effect || known_lease != lease {
                return Err("local importer reused for a different effect or lease".into());
            }
            return Ok(WorkReport::known(1, true));
        }
        let verified = verify(&self.corpus, &self.case_id, &self.phase)?;
        self.performed = Some((effect.clone(), lease.into(), verified));
        Ok(WorkReport::known(1, true))
    }
}
impl SourceObservationWork for PumpObservationWork {
    fn source_observation(&self, target: TargetBinding) -> Check<SourceObservation> {
        let (effect, lease, verified) = self
            .performed
            .as_ref()
            .ok_or("local source import did not perform")?;
        if *effect != target.effect
            || *lease != target.lease
            || target.generation != Generation::INITIAL
            || target.provider != PROVIDER
        {
            return Err("source receipt target does not match performed local work".into());
        }
        Ok(SourceObservation {
            target,
            source_repository: "llgtrn/Mechatron".into(),
            source_commit: SOURCE_COMMIT.into(),
            source_path: SOURCE_PATH.into(),
            corpus: verified.raw_corpus.clone(),
            case: verified.case_id.as_bytes().to_vec(),
            phase: verified.phase.as_bytes().to_vec(),
            outcome: verified.outcome,
        })
    }
}
